<template><div class="page"><v-card flat class="hero pa-5 mb-4"><div class="d-flex align-center flex-wrap"><div><div class="text-overline">SALES CRM</div><h1 class="text-h5 font-weight-bold">Leads</h1><div class="grey--text">Track prospects from enquiry to conversion.</div></div><v-spacer/><v-btn color="#165134" dark depressed @click="openCreate"><v-icon left>mdi-account-plus</v-icon>New Lead</v-btn></div></v-card><v-card flat class="pa-3 mb-4"><v-row dense align="center"><v-col cols="12" md="5"><v-text-field v-model="search" dense outlined clearable prepend-inner-icon="mdi-magnify" label="Search leads" @keyup.enter="load" @click:clear="load"/></v-col><v-col cols="12" md="3"><v-select v-model="status" :items="statuses" dense outlined clearable label="Status" @change="load"/></v-col><v-col cols="12" md="4" class="text-right"><v-chip class="mr-2">{{ total }} leads</v-chip><v-btn text @click="load"><v-icon left>mdi-refresh</v-icon>Refresh</v-btn></v-col></v-row></v-card><v-card flat><v-data-table :headers="headers" :items="items" :loading="loading" :server-items-length="total" :options.sync="options" @update:options="load"><template v-slot:item.status="{item}"><v-chip x-small dark :color="statusColor(item.status)">{{ item.status }}</v-chip></template><template v-slot:item.priority="{item}"><v-chip x-small outlined>{{ item.priority || 'medium' }}</v-chip></template><template v-slot:item.actions="{item}"><v-btn icon small @click="edit(item)"><v-icon small>mdi-pencil</v-icon></v-btn></template></v-data-table></v-card><v-dialog v-model="dialog" max-width="700"><v-card><v-card-title>{{ editing ? 'Edit Lead' : 'New Lead' }}<v-spacer/><v-btn icon @click="dialog=false"><v-icon>mdi-close</v-icon></v-btn></v-card-title><v-card-text><v-form @submit.prevent="save"><v-row><v-col cols="12" md="6"><v-text-field v-model="form.name" outlined dense label="Name *"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.phone" outlined dense label="Phone *"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.email" outlined dense label="Email"/></v-col><v-col cols="12" md="6"><v-select v-model="form.status" :items="statuses" outlined dense label="Status"/></v-col><v-col cols="12" md="6"><v-select v-model="form.priority" :items="priorities" outlined dense label="Priority"/></v-col><v-col cols="12" md="6"><v-autocomplete v-model="form.project_id" :items="projects" item-text="name" item-value="id" outlined dense clearable label="Interested Project" :loading="loadingProjects"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.budget" type="number" outlined dense label="Budget"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.next_follow_up" type="date" outlined dense label="Next Follow-up"/></v-col><v-col cols="12" md="6"><v-autocomplete v-model="form.assigned_to" :items="users" item-text="name" item-value="id" outlined dense clearable label="Assigned To" :loading="loadingUsers"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.source" outlined dense label="Source"/></v-col><v-col cols="12"><v-textarea v-model="form.notes" outlined dense rows="3" label="Notes"/></v-col></v-row></v-form></v-card-text><v-card-actions><v-spacer/><v-btn text @click="dialog=false">Cancel</v-btn><v-btn color="#165134" dark :loading="saving" @click="save">Save Lead</v-btn></v-card-actions></v-card></v-dialog></div></template><script>import api from '../../../services/api';export default{name:'Leads',data(){return{loading:false,saving:false,dialog:false,editing:null,search:'',status:null,total:0,items:[],projects:[],users:[],loadingProjects:false,loadingUsers:false,options:{page:1,itemsPerPage:15},statuses:['new','contacted','qualified','site_visit','negotiation','converted','lost'],priorities:['low','medium','high'],headers:[{text:'Lead #',value:'lead_number'},{text:'Name',value:'name'},{text:'Phone',value:'phone'},{text:'Source',value:'source'},{text:'Priority',value:'priority'},{text:'Status',value:'status'},{text:'Actions',value:'actions',sortable:false}],form:this.blank()}},mounted(){this.load()},methods:{blank(){return{name:'',phone:'',email:'',source:'',status:'new',priority:'medium',project_id:null,budget:null,next_follow_up:null,assigned_to:null,notes:''}},openCreate(){this.editing=null;this.form=this.blank();this.dialog=true;this.loadLookups()},edit(i){this.editing=i;this.form=Object.assign(this.blank(),i);this.dialog=true;this.loadLookups()},async loadLookups(){this.loadingProjects=true;this.loadingUsers=true;try{const [p,u]=await Promise.all([api.get('/projects',{params:{per_page:100}}),api.get('/sales-agents')]);this.projects=p.data.data||[];this.users=u.data.data||[]}catch(e){this.$root.$emit('show-error','Unable to load lead selections.')}finally{this.loadingProjects=false;this.loadingUsers=false}},async load(){this.loading=true;try{const r=await api.get('/leads',{params:{search:this.search,status:this.status,page:this.options.page,per_page:this.options.itemsPerPage}});this.items=r.data.data||[];this.total=r.data.total||0}finally{this.loading=false}},async save(){this.saving=true;try{if(this.editing)await api.put('/leads/'+this.editing.id,this.form);else await api.post('/leads',this.form);this.dialog=false;this.editing=null;await this.load()}catch(e){this.$root.$emit('show-error',(e.response&&e.response.data&&e.response.data.message)||'Unable to save lead.')}finally{this.saving=false}},statusColor(s){return{new:'grey',contacted:'blue',qualified:'indigo',site_visit:'orange',negotiation:'purple',converted:'success',lost:'error'}[s]||'grey'}}}</script><style scoped>.page{width:100%}.hero{border-left:4px solid #165134}</style>